  position: fixed;
  left: 0;
  bottom: 0;
  width: var(--monster-frame-w);
  height: var(--monster-frame-h);
  pointer-events: none;
  z-index: 999;
  transform: translateX(calc(-1 * var(--monster-frame-w)));
}

.monster-walker.is-walking {
  animation: monster-cross var(--monster-crossing) linear 1 forwards;
}

/* mirrored to face right, so it flips together with .monster-sprite below */
.monster-shadow {
  position: absolute;
  left: 8%;
  bottom: 0;
  width: 42%;
  height: 11px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 50%;
  filter: blur(3px);
}

.monster-sprite {
  position: absolute;
  inset: 0;
  background-image: url("assets/monster-sprite.png");
  background-repeat: no-repeat;
  background-size: var(--monster-sheet-w) var(--monster-frame-h);
  transform: scaleX(-1); /* sheet faces left; we walk left to right */
}

.monster-walker.is-walking .monster-sprite {
  animation: monster-walk-cycle var(--monster-cycle) steps(23) var(--monster-cycles);
}

@keyframes monster-walk-cycle {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--monster-sheet-w)) 0; }
}

@keyframes monster-cross {
  from { transform: translateX(calc(-1 * var(--monster-frame-w))); }
  to   { transform: translateX(100vw); }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walker.is-walking { animation: none; transform: translateX(40vw); }
  .monster-walker.is-walking .monster-sprite { animation: none; }
}

