const { chromium } = require('playwright-core');
const path = require('path');

const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const TARGET = '<home>\\source\\repos\\priv\\monster-dev-testruns\\2026-08-01-plan-sonnet\\index.html';

(async () => {
  const browser = await chromium.launch({ executablePath: CHROME, headless: true });
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  await page.goto('file:///' + TARGET.replace(/\\/g, '/'));
  await page.waitForTimeout(300);

  const shot = (name) => page.screenshot({ path: path.join(__dirname, name) });
  await shot('01-before.png');

  const readState = () => page.evaluate(() => {
    const w = document.querySelector('.monster-walker');
    const cs = getComputedStyle(w);
    return {
      isWalking: w.classList.contains('is-walking'),
      transform: cs.transform,
      crossing: w.style.getPropertyValue('--monster-crossing'),
      cycles: w.style.getPropertyValue('--monster-cycles'),
    };
  });

  console.log('BEFORE:', await readState());

  await page.keyboard.press('Alt+A');
  await page.waitForTimeout(500);
  await shot('02-just-after-trigger.png');
  console.log('JUST AFTER TRIGGER:', await readState());

  await page.waitForTimeout(2000);
  await shot('03-mid-walk.png');
  console.log('MID WALK (~2.5s in):', await readState());

  // Retrigger mid-walk — should be ignored (same crossing/cycles, no restart)
  const midState = await readState();
  await page.keyboard.press('Alt+A');
  await page.waitForTimeout(200);
  const afterRetrigger = await readState();
  console.log('RETRIGGER IGNORED?', JSON.stringify(midState) === JSON.stringify(afterRetrigger));

  await page.waitForTimeout(3000);
  await shot('04-further-along.png');
  console.log('FURTHER ALONG (~5.7s in):', await readState());

  // wait out the rest of the crossing (duration reported in --monster-crossing)
  const totalMs = parseFloat(midState.crossing) * 1000;
  const remaining = Math.max(0, totalMs - 5700 + 1000);
  await page.waitForTimeout(remaining);
  await shot('05-after-finish.png');
  console.log('AFTER FINISH:', await readState());

  // trigger again — should work since it reset
  await page.keyboard.press('Alt+A');
  await page.waitForTimeout(500);
  await shot('06-second-run.png');
  console.log('SECOND RUN:', await readState());

  console.log('CONSOLE/PAGE ERRORS:', errors);

  await browser.close();
})();

